// Read every row of dashboard_stock from THIS project and stamp it with
// today's Baghdad date. Paged, because PostgREST caps responses at 1000 rows.
const cfg = $('Config').first().json;
const base = cfg.supabaseUrl +
  '/rest/v1/dashboard_stock?select=product_id,on_hand_qty,stock_value&order=product_id.asc';
const hdr = { apikey: cfg.serviceKey, Authorization: 'Bearer ' + cfg.serviceKey };

const all = [];
for (let offset = 0; offset < 500000; offset += 1000) {
  const page = await this.helpers.httpRequest({
    method: 'GET', url: base + '&limit=1000&offset=' + offset, headers: hdr, json: true });
  const rows = Array.isArray(page) ? page : [];
  all.push(...rows);
  if (rows.length < 1000) break;
}

// Baghdad, not UTC: a 03:00 Baghdad run is still the previous day in UTC, and
// stamping it as such would put two snapshots on one date and none on another.
const snap_date = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Baghdad' });

const rows = all.map(s => ({
  product_id:  s.product_id,
  snap_date,
  on_hand_qty: Number(s.on_hand_qty) || 0,
  stock_value: s.stock_value == null ? null : Number(s.stock_value)
}));

if (!rows.length) throw new Error('dashboard_stock is empty - run the products+stock sync first');
return [{ json: { rows, count: rows.length, snap_date } }];

const rows = $json.rows || [];
const CH = 500, items = [];
for (let i = 0; i < rows.length; i += CH) items.push({ json: { rows: rows.slice(i, i + CH) } });
return items.length ? items : [{ json: { rows: [] } }];
